def langford(n):
    seq = [0] * (2 * n)
    def place(k):
        if k == 0:
            return True
        for i in range(2 * n - k - 1):
            j = i + k + 1
            if seq[i] == 0 and seq[j] == 0:
                seq[i] = k
                seq[j] = k
                if place(k - 1):
                    return True
                seq[i] = 0
                seq[j] = 0
        return False
    if place(n):
        return seq
    else:
        return None
result = langford(11)
print(result)
